const ACCOUNT = 'REEMPLAZAR_CORREO_CUENTA_A';

// ── Reglas autónomas (edita libremente) ─────────────────────────
const OWN_SENDERS = []; // direcciones o schénula regex: ['ana@ejemplo.com', /@mibanco\./i]
const PROMO_RX = /(unsubscribe|newsletter|oferta|descuento|promo|deal|coupon|black friday|sale|expiración|invitación a suscribirse|marketing)/i;
const BOT_SENDERS = /(no-?reply|donotreply|noreply@|mailer-daemon|notificaciones@|avisos@)/i;
const IMPORTANT_SUBJECT = /(urgente|urgent|action required|acció|reunión|meeting|invoice|factura|pago|payment|security|seguridad|banco|deadline|important)/i;
const IMPORTANT_LABELS = new Set(['IMPORTANT']);

const j = $input.item.json;
const h = j.headers || {};
const labels = j.labelIds || [];
const from = h.from || j.from || '';

let important = false;
const reasons = [];

if (OWN_SENDERS.some((rx) => (typeof rx === 'string' ? from.toLowerCase().includes(rx.toLowerCase()) : rx.test(from)))) {
  important = true; reasons.push('sender allowlist');
}
if (labels.includes('FLAGGED')) { important = true; reasons.push('FLAGGED'); }
if (labels.some((l) => IMPORTANT_LABELS.has(l))) { important = true; reasons.push('Gmail IMPORTANT'); }
if (IMPORTANT_SUBJECT.test(h.subject || '')) { important = true; reasons.push('subject keywords'); }
if (!important && (PROMO_RX.test(from) || PROMO_RX.test(h.subject || '') || BOT_SENDERS.test(from))) {
  reasons.push('filtered: promo/bot');
}

return {
  json: {
    account: ACCOUNT,
    gmail_id: j.id,
    thread_id: j.threadId || null,
    subject: h.subject || null,
    sender: from || null,
    snippet: String(j.snippet ?? '').slice(0, 2000) || null,
    received_at: h.date ? new Date(h.date).toISOString() : null,
    unread: labels.includes('UNREAD'),
    important,
    importance_reason: reasons.join(', ') || null,
    labels,
  },
};

